/* 停留时序（秒），辨识期 PD 增益 —— 纯 PD，**无任何重力前馈** */
#define ARM_TRAJ_KP         25.0f
#define ARM_TRAJ_KD         2.0f
/* 双向逼近偏置（rad）。两遍从相反方向逼近，静摩擦残留符号相反才能抵消。 */
#define ARM_TRAJ_MOVE_BIAS_RAD  0.0349066f
#define ARM_TRAJ_SETTLE_S   1.2f
#define ARM_TRAJ_AVG_S      0.4f

/* 静止判据：|dq| 低于该值并持续 ARM_TRAJ_STILL_MS 毫秒才算静止。
 *
 * 阈值定在这里是有依据的，不是随手取：机械臂在库仑摩擦下会停在一个**极限环**
 * 上微微"呼吸"，实测约 0.029 rad/s（用带重力+摩擦的假机械臂驱动本状态机测出）。
 * 那个速度对应的粘滞力矩是 b*0.029 = 0.010 N*m，仅为峰值补偿 4.15 N*m 的 0.24%，
 * 远低于编码器量化噪声 —— 它是抖动而不是运动。
 * 定 0.02 会让每一次停留都等不到静止、全部超时（实测 42/56 被跳过）。
 * 定 0.05 既能收进极限环，又把粘滞污染压在 0.5% 以内。
 *
 * 这两个数是要在真机上现场复核的常数：先用 --simulate 看 skipped 数，
 * 若 >0 就把阈值调大，然后重新确认辨识出的云图 RMS 仍 < 0.05 N*m。 */
#define ARM_TRAJ_STILL_RADPS  0.05f
#define ARM_TRAJ_STILL_MS     100u
#define ARM_TRAJ_SETTLE_TIMEOUT_MS 3000u   /* 超时则跳过该点，不卡死 */



